#include "codegen.h"

static int emit(Compiler *c, Opcode op, int64_t operand, char *str_op) {
    if (c->code_count >= MAX_BYTECODE) { fprintf(stderr, "bytecode overflow\n"); return -1; }
    Instruction *ins = &c->code[c->code_count];
    ins->op = op; ins->operand = operand; ins->str_operand = str_op;
    return c->code_count++;
}

static int resolve_local(Compiler *c, const char *name) {
    for (int i = c->local_count - 1; i >= 0; i--) {
        if (strcmp(c->locals[i].name, name) == 0) return i;
    }
    return -1;
}

static int resolve_capture(Compiler *c, const char *name) {
    for (int i = 0; i < c->capture_count; i++)
        if (strcmp(c->captures[i].name, name) == 0) return i;
    return -1;
}

static int add_local(Compiler *c, const char *name) {
    if (c->local_count >= MAX_LOCALS) { fprintf(stderr, "too many local variables\n"); return -1; }
    Local *local = &c->locals[c->local_count];
    strncpy(local->name, name, MAX_IDENT_LEN - 1); local->name[MAX_IDENT_LEN - 1] = '\0';
    local->scope_depth = c->scope_depth;
    local->is_boxed = 0;
    return c->local_count++;
}

static int find_function(Compiler *c, const char *name) {
    for (int i = 0; i < c->func_count; i++) {
        if (strcmp(c->functions[i].name, name) == 0) return i;
    }
    return -1;
}

