static ASTNode *parse_primary(Parser *p) {
    if (match(p, TOK_NUM)) {
        ASTNode *n = ast_alloc(); n->type = NODE_NUM_LIT; n->line = prev(p)->line;
        n->data.num_val = prev(p)->literal.ival; return n;
    }
    if (match(p, TOK_STRING)) {
        ASTNode *n = ast_alloc(); n->type = NODE_STR_LIT; n->line = prev(p)->line;
        strncpy(n->data.str_val, prev(p)->text, MAX_STRING_LEN - 1); return parse_postfix(p, n);
    }
    if (match(p, TOK_TRUE) || match(p, TOK_FALSE)) {
        ASTNode *n = ast_alloc(); n->type = NODE_BOOL_LIT; n->line = prev(p)->line;
        n->data.bool_val = (prev(p)->type == TOK_TRUE) ? 1 : 0; return n;
    }
    if (match(p, TOK_IDENT)) {
        char name[MAX_IDENT_LEN];
        strncpy(name, prev(p)->text, MAX_IDENT_LEN - 1); name[MAX_IDENT_LEN - 1] = '\0';
        int line = prev(p)->line;
        if (match(p, TOK_LPAREN)) {
            ASTNode *n = ast_alloc(); n->type = NODE_CALL; n->line = line;
            strncpy(n->data.call.name, name, MAX_IDENT_LEN - 1);
            nodelist_init(&n->data.call.args);
