            expect(p, TOK_RPAREN, "')'"); return parse_postfix(p, n);
        }
        ASTNode *obj = ast_alloc(); obj->type = NODE_IDENT; obj->line = line;
        strncpy(obj->data.ident, name, MAX_IDENT_LEN - 1);
        return parse_postfix(p, obj);
    }
