static int map_delete(MapData *m, const char *key) {
    int i = map_find(m, key);
    if (i < 0) return 0;
    free(m->keys[i]);
    for (int j = i; j < m->len - 1; j++) { m->keys[j] = m->keys[j+1]; m->values[j] = m->values[j+1]; }
    m->len--;
    return 1;
}


static int resolve_global(VM *vm, const char *name) {
    for (int i = 0; i < vm->global_count; i++)
        if (strcmp(vm->global_names[i], name) == 0) return i;
    return -1;
}

static int add_global(VM *vm, const char *name) {
    if (vm->global_count >= MAX_GLOBALS) { fprintf(stderr, "too many globals\n"); return -1; }
    int idx = vm->global_count;
    strncpy(vm->global_names[idx], name, MAX_IDENT_LEN - 1);
    vm->globals[idx].type = VAL_NULL;
    vm->global_count++;
    return idx;
}

static int64_t value_to_int(Value v) {
    if (v.type == VAL_REF) return value_to_int(*v.data.ref);
    switch (v.type) { case VAL_INT: return v.data.ival; case VAL_BOOL: return v.data.bval ? 1 : 0; default: return 0; }
}

static int value_is_integer_like(Value v) {
    if (v.type == VAL_REF) return value_is_integer_like(*v.data.ref);
    return v.type == VAL_INT || v.type == VAL_BOOL;
