static int values_equal(Value a, Value b) {
    if (a.type == VAL_REF) return values_equal(*a.data.ref, b);
    if (b.type == VAL_REF) return values_equal(a, *b.data.ref);
    if (a.type != b.type) return 0;
    switch (a.type) {
        case VAL_INT: return a.data.ival == b.data.ival;
        case VAL_BOOL: return a.data.bval == b.data.bval;
        case VAL_STR: return strcmp(a.data.sval, b.data.sval) == 0;
        case VAL_NULL: return 1;
        default: return 0;
    }
}

