#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lexer.h"
#include "parser.h"
#include "codegen.h"
#include "vm.h"

static char *read_file(const char *path) {
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "cannot open file: %s\n", path); return NULL; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    if (size > 0) {
        fseek(f, 0, SEEK_SET);
        char *buf = malloc(size + 1);
        if (!buf) { fclose(f); return NULL; }
        size_t rd = fread(buf, 1, size, f);
        buf[rd] = '\0';
        fclose(f);
        return buf;
    }
    fseek(f, 0, SEEK_SET);
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) { fclose(f); return NULL; }
    size_t rd;
    while ((rd = fread(buf + len, 1, cap - len - 1, f)) > 0) {
        len += rd;
        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
    }
    buf[len] = '\0';
    fclose(f);
    return buf;
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: minicc <file.mini>\n"); return 1; }
    char *source = read_file(argv[1]);
    if (!source) return 1;

    Lexer lex;
    lexer_init(&lex, source);
    if (lexer_tokenize(&lex) < 0) { free(source); return 1; }

    Parser parser;
    parser_init(&parser, lex.tokens, lex.token_count);
    ASTNode *program = parse_program(&parser);
    if (parser.had_error) { free(source); ast_free_all(); return 1; }

    Compiler compiler;
    compiler_init(&compiler);
    if (compile(&compiler, program) < 0) { free(source); ast_free_all(); return 1; }

    VM vm;
    vm_init(&vm, &compiler);
    int result = vm_run(&vm);

    free(source);
    ast_free_all();
    return result;
}
